// 1. Obtenemos el output que contiene el texto con el JSON
const rawOutput = $input.first().json.data;

try {
    const fullJson = rawOutput;
    const actions = fullJson.pending_actions || [];
    const status = fullJson.status;
    const swagger_definition = fullJson.swagger_definition;
    const project_overview = fullJson.project_overview;
    const work_plan = fullJson.work_plan;

    return {
        status,
        has_gemini: actions.some(a => ["[GEMINI]"].includes(a.tag)),
        has_human: actions.some(a => ["[ASK_CRIS]", "[SWAGGER_PROPOSAL]", "[PROPOSAL]"].includes(a.tag)),
        gemini_tasks: actions.filter(a => a.tag === "[GEMINI]"),
        human_tasks: actions.filter(a => a.tag !== "[GEMINI]"),
        swagger_definition,
        project_overview,
        work_plan,
        // Devolvemos el JSON ya procesado para que el resto del flujo lo use fácil
        data: fullJson
    };
} catch (error) {
    // Si algo falla, te devuelve el error para debuggear en la interfaz de n8n
    return {
        status: "RAW_TEXT_RESPONSE",
        has_gemini: false,
        has_human: true,
        human_tasks: [{ 
            tag: "[ASK_CRIS]", 
            message: "La IA no generó un JSON, sino un documento técnico. ¿Deseas procesarlo manualmente?" 
        }],
        project_overview: { validation_notes: "0x02 - Non-JSON Payload received" },
        raw_text: rawOutput // Aquí capturamos todo el plan que escribió
    };
}

