const masterId = $input.first().json.id;
const plan = $('JS Pending Actions').first().json.work_plan;

return plan.map(task => {
    // Forzamos a que depends_on sea SIEMPRE un array válido para Postgres
    let rawDepends = task.depends_on;
    let finalDepends = [];

    if (Array.isArray(rawDepends)) {
        finalDepends = rawDepends;
    } else if (rawDepends !== null && rawDepends !== undefined && rawDepends !== "") {
        // Si es un número o un string que representa un número, lo metemos en un array
        finalDepends = [parseInt(rawDepends)];
    }
    // Si es null o vacío, se queda como [] (Postgres acepta un array vacío para int[])

    return {
        work_plan_execution_id: masterId,
        task_id: task.task_id,
        task_role: task.task_role,
        label: task.label,
        description: task.description,
        technical_context: task.technical_context,
        can_parallize: !!task.can_parallelize, // Forzamos booleano
        depends_on: finalDepends, // n8n lo mapeará correctamente a {1,2,3} en Postgres
        output_data: 'PENDING'
    };
});

