// 1. Obtenemos el texto crudo del nodo anterior
let rawInput = $input.first().json.output;

// 1) Elimina bloques completos de "pensamiento" del modelo distill
//    Forma:  <|channel>thought ... texto ... <channel|>
//    Usamos [\s\S] porque el bloque suele tener saltos de línea.
rawInput = rawInput.replace(/<\|channel>[\s\S]*?<channel\|>/g, "");

// 2) Por si queda algún token suelto sin su pareja (respuestas truncadas)
rawInput = rawInput.replace(/<\|channel>/g, "");
rawInput = rawInput.replace(/<channel\|>/g, "");

// 3) Limpia también tokens Harmony estándar por si el modelo mezcla formatos
rawInput = rawInput.replace(/<\|[a-z_]+\|>/gi, "");

// 4) Etiquetas de canal sueltas al inicio ("thought", "analysis", "final", "commentary")
rawInput = rawInput.replace(/^\s*(thought|analysis|final|commentary)\s*\n/i, "");

rawInput = rawInput.trim();

// 2. Función "anti-terquedad" con RegExp seguro para editores visuales
// Usamos `{3} para buscar las 3 comillas invertidas sin romper el markdown
function extractAndParseJSON(text) {
    // 1) Probar bloque ```json ... ```
    const fenceMatch = text.match(/`{3}(?:json)?\s*([\s\S]*?)\s*`{3}/);
    if (fenceMatch && fenceMatch[1]) {
        try { return JSON.parse(fenceMatch[1]); } catch(e) {}
    }
    // 2) Probar texto tal cual
    try { return JSON.parse(text.trim()); } catch(e) {}
    // 3) Fallback: extraer desde el primer { hasta el último } balanceado
    const firstBrace = text.indexOf('{');
    const lastBrace = text.lastIndexOf('}');
    if (firstBrace !== -1 && lastBrace > firstBrace) {
        try { return JSON.parse(text.substring(firstBrace, lastBrace + 1)); } catch(e) {}
    }
    return null;
}

// 3. El Validador Estricto (Tu Tech Lead automatizado)
function validateSchema(data) {
    const errors = [];

    // --- 1. Validar Status ---
    const validStatuses = ["READY", "MISSING_SWAGGER", "UNDER_INQUIRY", "PROPOSE_TO_CRIS", "ASK_CRIS"];
    if (!validStatuses.includes(data.status)) {
        errors.push(`Invalid 'status'. Received: ${data.status}`);
    }

    // --- 2. Validar Project Overview ---
    const po = data.project_overview;
    if (!po || typeof po !== 'object') {
        errors.push("'project_overview' is missing or it is not an object.");
    } else {
        if (typeof po.architecture !== 'string') errors.push("'project_overview.architecture' must be string.");
        if (typeof po.swagger_definition !== 'string') errors.push("'project_overview.swagger_definition' must be string.");
        if (typeof po.validation_notes !== 'string') errors.push("'project_overview.validation_notes' must be string.");

        const stack = po.stack_details;
        if (!stack || typeof stack !== 'object') {
            errors.push("'stack_details' is missing or it is not an object.");
        } else {
            if (typeof stack.backend !== 'string') errors.push("'stack_details.backend' must be string.");
            if (typeof stack.frontend !== 'string') errors.push("'stack_details.frontend' must be string.");
            if (typeof stack.database !== 'string') errors.push("'stack_details.database' must be string.");
            if (!Array.isArray(stack.others)) errors.push("'stack_details.others' It must be an array.");
        }
    }

    // --- 3. Validar Work Plan ---
    if (!Array.isArray(data.work_plan)) {
        errors.push("'work_plan' It must be an array.");
    } else {
        const validRoles = ["THINKING_TASK", "EXECUTION_TASK", "VALIDATION_TASK"];
        const validLabels = ["[PC_BIG]", "[PORTABLE]", "[GEMINI]", "[CLAUDE]"];

        data.work_plan.forEach((task, index) => {
            const taskPath = `work_plan[${index}]`;
            if (typeof task.task_id !== 'number') errors.push(`${taskPath}.task_id must be number.`);
            if (!validRoles.includes(task.task_role)) errors.push(`${taskPath}.task_role invalid: ${task.task_role}`);
            if (!validLabels.includes(task.label)) errors.push(`${taskPath}.label invalid: ${task.label}`);

            // Validaciones duales (Inglés / Español)
            if (typeof task.description !== 'string') errors.push(`${taskPath}.description must be string.`);
            if (typeof task.description_spanish !== 'string') errors.push(`${taskPath}.description_spanish must be string.`);
            if (typeof task.technical_context !== 'string') errors.push(`${taskPath}.technical_context must be string.`);
            if (typeof task.technical_context_spanish !== 'string') errors.push(`${taskPath}.technical_context_spanish must be string.`);

            if (typeof task.can_parallelize !== 'boolean') errors.push(`${taskPath}.can_parallelize must be boolean.`);
            if (typeof task.estimated_hours !== 'number') errors.push(`${taskPath}.estimated_hours must be number.`);

            // Validación de depends_on (Array de números o null)
            if (task.depends_on !== null) {
                if (!Array.isArray(task.depends_on) || !task.depends_on.every(d => typeof d === 'number')) {
                    errors.push(`${taskPath}.depends_on must be an array of numbers or null.`);
                }
            }
        });
    }

    // --- 4. Validar Pending Actions ---
    if (!Array.isArray(data.pending_actions)) {
        errors.push("'pending_actions' It must be an array.");
    } else {
        const validTags = ["[ASK_CRIS]", "[GEMINI]", "[PROPOSAL]", "[SWAGGER_PROPOSAL]"];
        data.pending_actions.forEach((action, index) => {
            const actionPath = `pending_actions[${index}]`;
            if (!validTags.includes(action.tag)) errors.push(`${actionPath}.tag invalid: ${action.tag}`);
            if (typeof action.message !== 'string') errors.push(`${actionPath}.message must be string.`);
        });
    }

    return errors;
}

// 4. Ejecución principal
const parsedData = extractAndParseJSON(rawInput);

if (!parsedData) {
    return {
        isValid: false,
        error_type: "PARSE_ERROR",
        error_message: "The response sent did not comply with your system prompt structure. Review the errors found and send the response again. Remember to always respect your system prompt and the structure of the response JSON.",
        details: null,
        parsed_data: rawInput
    };
}

const validationErrors = validateSchema(parsedData);

if (validationErrors.length > 0) {
    return {
        isValid: false,
        error_type: "SCHEMA_ERROR",
        error_message: "The JSON was parsed, but it breaks the rules of the system prompt contract.",
        details: validationErrors,
        parsed_data: parsedData
    };
}

// 5. ¡Paso a producción!
return {
    isValid: true,
    data: parsedData
};
